# DUCK BANNER v3 - Optimizado Kali Linux + Termux
# Ancho 64 - cabe en celular y en PC, centrado automatico
# Uso: ./duck-banner.sh | ./duck-banner.sh neon | ./duck-banner.sh classic | ./duck-banner.sh --no-color
clear
MODE="${1:-neon}"
# Detectar ancho de terminal
COLS=$(tput cols 2>/dev/null || echo 80)
ART_W=64
# Centrar: calcular padding
